const input = $input.first().json || {};

function normalize(value) {
  return value === undefined || value === null
    ? ""
    : String(value).trim().toLowerCase();
}

function normalizePhone(value) {
  return normalize(value).replace(/[^0-9]/g, "");
}

function domainFromWebsite(value) {
  const raw = normalize(value);
  if (!raw) return "";

  try {
    const withProtocol = raw.startsWith("http") ? raw : `https://${raw}`;
    return new URL(withProtocol).hostname.replace(/^www\./, "");
  } catch (error) {
    return raw.replace(/^https?:\/\//, "").replace(/^www\./, "").split("/")[0];
  }
}

function emailDomain(value) {
  const email = normalize(value);
  if (!email.includes("@")) return "";
  return email.split("@")[1];
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-D",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        dedupe: {
          status: "failed",
          decision: null,
          recommended_action: null,
          best_match: null,
          best_score: null,
          checked_candidates: 0,
          match_reasons: []
        },
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const payload = source.payload || {};
const rules = config.rules || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-D will not run dedupe when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "dedupe_check") {
  return fail({
    code: "DEDUPE_NOT_REQUESTED",
    message: "source.next_action is not dedupe_check.",
    details: [{ next_action: source.next_action || null }]
  });
}

const candidates = Array.isArray(config.candidate_records)
  ? config.candidate_records
  : [];

const scores = {
  exact_email_score: Number(rules.exact_email_score ?? 100),
  exact_phone_score: Number(rules.exact_phone_score ?? 90),
  exact_domain_score: Number(rules.exact_domain_score ?? 70),
  exact_company_score: Number(rules.exact_company_score ?? 50),
  exact_name_score: Number(rules.exact_name_score ?? 30),
  duplicate_threshold: Number(rules.duplicate_threshold ?? 90),
  possible_duplicate_threshold: Number(rules.possible_duplicate_threshold ?? 60)
};

const incoming = {
  name: normalize(payload.name || [payload.firstname, payload.lastname].filter(Boolean).join(" ")),
  email: normalize(payload.email),
  phone: normalizePhone(payload.phone),
  company: normalize(payload.company),
  website_domain: domainFromWebsite(payload.website),
  email_domain: emailDomain(payload.email)
};

let bestMatch = null;
let bestScore = 0;
let bestReasons = [];
const candidateResults = [];

for (const candidate of candidates) {
  let score = 0;
  const reasons = [];

  const candidateNormalized = {
    record_id: candidate.record_id || null,
    name: normalize(candidate.name || [candidate.firstname, candidate.lastname].filter(Boolean).join(" ")),
    email: normalize(candidate.email),
    phone: normalizePhone(candidate.phone),
    company: normalize(candidate.company),
    website_domain: domainFromWebsite(candidate.website),
    email_domain: emailDomain(candidate.email),
    source: candidate.source || null
  };

  if (incoming.email && candidateNormalized.email && incoming.email === candidateNormalized.email) {
    score += scores.exact_email_score;
    reasons.push("exact_email_match");
  }

  if (incoming.phone && candidateNormalized.phone && incoming.phone === candidateNormalized.phone) {
    score += scores.exact_phone_score;
    reasons.push("exact_phone_match");
  }

  const incomingDomain = incoming.website_domain || incoming.email_domain;
  const candidateDomain = candidateNormalized.website_domain || candidateNormalized.email_domain;

  if (incomingDomain && candidateDomain && incomingDomain === candidateDomain) {
    score += scores.exact_domain_score;
    reasons.push("exact_domain_match");
  }

  if (incoming.company && candidateNormalized.company && incoming.company === candidateNormalized.company) {
    score += scores.exact_company_score;
    reasons.push("exact_company_match");
  }

  if (incoming.name && candidateNormalized.name && incoming.name === candidateNormalized.name) {
    score += scores.exact_name_score;
    reasons.push("exact_name_match");
  }

  const result = {
    record_id: candidate.record_id || null,
    source: candidate.source || null,
    score,
    match_reasons: reasons
  };

  candidateResults.push(result);

  if (score > bestScore) {
    bestScore = score;
    bestMatch = {
      record_id: candidate.record_id || null,
      source: candidate.source || null,
      candidate_snapshot: candidate
    };
    bestReasons = reasons;
  }
}

let decision = "new_record";
let recommendedAction = "create_record";
let status = "clear";

if (bestScore >= scores.duplicate_threshold) {
  decision = "duplicate";
  recommendedAction = "update_existing_record";
  status = "duplicate_found";
} else if (bestScore >= scores.possible_duplicate_threshold) {
  decision = "possible_duplicate";
  recommendedAction = "manual_review";
  status = "possible_duplicate_found";
}

return [
  {
    json: {
      success: true,
      component_id: "C2-D",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      dedupe: {
        status,
        decision,
        recommended_action: recommendedAction,
        best_match: bestMatch,
        best_score: bestScore,
        checked_candidates: candidates.length,
        match_reasons: bestReasons,
        candidate_results: candidateResults,
        thresholds: {
          duplicate_threshold: scores.duplicate_threshold,
          possible_duplicate_threshold: scores.possible_duplicate_threshold
        }
      },
      source_result: source,
      error: null,
      next_action:
        recommendedAction === "create_record"
          ? (config.default_next_action || "write_record")
          : recommendedAction
    }
  }
];
